<div class="partner-promo-field">
    <div class="partner-promo-label-row"><label class="partner-promo-label" for="partner-promo-code">Code promotionnel partenaire</label><span class="partner-promo-optional">Facultatif</span></div>
    <div class="partner-promo-input-wrap"><i class="bi bi-ticket-perforated partner-promo-input-icon" aria-hidden="true"></i><input id="partner-promo-code" class="partner-promo-input" type="text" maxlength="24" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Saisissez votre code" aria-describedby="partner-promo-help partner-promo-status"><button type="button" class="partner-promo-clear" data-promo-clear aria-label="Effacer le code" hidden><i class="bi bi-x-lg" aria-hidden="true"></i></button></div>
    <p id="partner-promo-help" class="partner-promo-help">Le code est vérifié automatiquement avant le paiement.</p>
    <div id="partner-promo-status" class="partner-promo-status" data-state="empty" role="status" aria-live="polite"><i id="partner-promo-status-icon" class="bi bi-ticket-perforated" aria-hidden="true"></i><span id="partner-promo-status-text">Aucun code saisi</span></div>
</div>
